{
  "openapi": "3.1.1",
  "info": {
    "title": "Order API",
    "description": "Checkout stand-in for the pizza ordering platform.",
    "version": "v1"
  },
  "paths": {
    "/v1/pizzas": {
      "get": {
        "summary": "GET /v1/pizzas",
        "operationId": "get_v1_pizzas",
        "description": "List available pizzas.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/orders": {
      "post": {
        "summary": "POST /v1/orders \u2014 checkout with coupon",
        "operationId": "post_v1_orders",
        "description": "Submit order; client total is discarded \u2014 server re-prices authoritatively.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "couponCode": "SAVE10",
                "cart": {
                  "lines": [
                    {
                      "lineId": "line-1",
                      "pizzaId": "margherita",
                      "category": "classic",
                      "unitPrice": 9.50,
                      "quantity": 2
                    },
                    {
                      "lineId": "line-2",
                      "pizzaId": "bbq-chicken",
                      "category": "meat",
                      "unitPrice": 12.00,
                      "quantity": 1
                    }
                  ]
                }
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/orders/{orderId}": {
      "get": {
        "summary": "GET /v1/orders/{orderId}",
        "operationId": "get_v1_orders_orderId",
        "description": "Read order by id.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/openapi/v1.json": {
      "get": {
        "summary": "GET /openapi/v1.json",
        "operationId": "get_openapi_v1.json",
        "description": "Live OpenAPI JSON while running in Development."
      }
    }
  },
  "components": {
    "securitySchemes": {
      "bearerAuth": {
        "type": "http",
        "scheme": "bearer",
        "bearerFormat": "JWT"
      }
    }
  }
}
